// Lookup for the 12x12 CJK bitmap font (font_cjk_data.cpp, generated by
// tools/gen_cjk_font.py). Without HG_CJK_FONT the font is not compiled in and every
// code point is one column wide, as before.
#include "hg/font.hpp"
#include "hg/font_cjk.hpp"

namespace hg::font {

#if HG_CJK_FONT

const uint8_t* cjk_glyph(char32_t cp) {
  int lo = 0, hi = kCjkGlyphCount - 1;
  while (lo <= hi) {
    const int mid = (lo + hi) / 2;
    if (kCjkCodepoints[mid] == cp) return kCjkBitmaps + mid * kCjkBytes;
    if (kCjkCodepoints[mid] < cp) lo = mid + 1;
    else hi = mid - 1;
  }
  return nullptr;
}

int columns(char32_t cp) {
  // CJK, kana, hangul and fullwidth forms: a glyph, or a '?' box if the font lacks it.
  // Emoji and other symbols stay one column.
  const bool wide = (cp >= 0x2E80 && cp <= 0xA4CF) || (cp >= 0xAC00 && cp <= 0xD7A3) || (cp >= 0xF900 && cp <= 0xFAFF) ||
                    (cp >= 0xFE30 && cp <= 0xFE4F) || (cp >= 0xFF00 && cp <= 0xFF60) || (cp >= 0xFFE0 && cp <= 0xFFE6) ||
                    (cp >= 0x20000 && cp <= 0x3FFFD);
  return wide ? 2 : 1;
}

#else

const uint8_t* cjk_glyph(char32_t) { return nullptr; }

int columns(char32_t) { return 1; }

#endif

}  // namespace hg::font
